      END IF;
    END IF;
  END PROCESS delay_ScvalidOut_process;


  
  switch_compare_1 <= '1' WHEN validOut > '0' ELSE
      '0';

  dataZeroScNoNvar <= to_signed(16#000000#, 21);

  bpskDataOut_signed <= signed(bpskDataOut);

  delay_bpskScDataOut_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        delay_bpskScDataOut_reg <= (OTHERS => to_signed(16#000000#, 21));
      ELSIF enb = '1' THEN
        delay_bpskScDataOut_reg(0) <= bpskDataOut_signed;
        delay_bpskScDataOut_reg(1 TO 12) <= delay_bpskScDataOut_reg(0 TO 11);
      END IF;
    END IF;
  END PROCESS delay_bpskScDataOut_process;

  bpskDataOutDelay <= delay_bpskScDataOut_reg(12);

  qpskDataOut_signed <= signed(qpskDataOut);

  delay_qpskScDataOut_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        delay_qpskScDataOut_reg <= (OTHERS => to_signed(16#000000#, 21));
      ELSIF enb = '1' THEN
        delay_qpskScDataOut_reg(0) <= qpskDataOut_signed;
        delay_qpskScDataOut_reg(1 TO 12) <= delay_qpskScDataOut_reg(0 TO 11);
      END IF;
    END IF;
  END PROCESS delay_qpskScDataOut_process;

  qpskDataOutDelay <= delay_qpskScDataOut_reg(12);

  psk8DataOut_signed <= signed(psk8DataOut);

  delay_psk8ScDataOut_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        delay_psk8ScDataOut_reg <= (OTHERS => to_signed(16#000000#, 21));
      ELSIF enb = '1' THEN
        delay_psk8ScDataOut_reg(0) <= psk8DataOut_signed;
        delay_psk8ScDataOut_reg(1 TO 9) <= delay_psk8ScDataOut_reg(0 TO 8);
      END IF;
    END IF;
  END PROCESS delay_psk8ScDataOut_process;

  psk8DataOutDelay <= delay_psk8ScDataOut_reg(9);

  apsk16DataOut_signed <= signed(apsk16DataOut);

  delay_apsk16ScDataOut_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        apsk16DataOutDelay <= to_signed(16#000000#, 21);
      ELSIF enb = '1' THEN
        apsk16DataOutDelay <= apsk16DataOut_signed;
      END IF;
    END IF;
  END PROCESS delay_apsk16ScDataOut_process;


  apsk32DataOut_signed <= signed(apsk32DataOut);

  
  dataOutDelay <= bpskDataOutDelay WHEN modIndxSigDelay1 = to_unsigned(16#1#, 3) ELSE
      qpskDataOutDelay WHEN modIndxSigDelay1 = to_unsigned(16#2#, 3) ELSE
      psk8DataOutDelay WHEN modIndxSigDelay1 = to_unsigned(16#3#, 3) ELSE
      apsk16DataOutDelay WHEN modIndxSigDelay1 = to_unsigned(16#4#, 3) ELSE
      apsk32DataOut_signed;

  delay_dataOutDelay1NoNVar_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        dataOutDelay1NoNVar <= to_signed(16#000000#, 21);
      ELSIF enb = '1' THEN
        dataOutDelay1NoNVar <= dataOutDelay;
      END IF;
    END IF;
  END PROCESS delay_dataOutDelay1NoNVar_process;


  
  dataOut <= dataZeroScNoNvar WHEN switch_compare_1 = '0' ELSE
      dataOutDelay1NoNVar;

  out0 <= std_logic_vector(dataOut);

  out1 <= validOut;

END rtl;

